import React, { useState, useEffect } from 'react';
import { Sun, Moon, Globe, Menu, X, ChevronDown, User, LogIn, UserPlus } from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';

// Traductions pour le header
const translations = {
  en: {
    home: 'Home',
    about: 'About',
    services: 'Services',
    portfolio: 'Portfolio',
    contact: 'Contact',
    language: 'Language',
    theme: 'Theme',
    light: 'Light',
    dark: 'Dark',
    system: 'System',
    welcome: 'Welcome',
    login: 'Login',
    register: 'Register',
    profile: 'Profile',
    logout: 'Logout',
    dashboard: 'Dashboard',
    getStarted: 'Get Started',
  },
  fr: {
    home: 'Accueil',
    about: 'À propos',
    services: 'Services',
    portfolio: 'Portfolio',
    contact: 'Contact',
    language: 'Langue',
    theme: 'Thème',
    light: 'Clair',
    dark: 'Sombre',
    system: 'Système',
    welcome: 'Bienvenue',
    login: 'Connexion',
    register: 'Inscription',
    profile: 'Profil',
    logout: 'Déconnexion',
    dashboard: 'Tableau de bord',
    getStarted: 'Commencer',
  },
  mg: {
    home: 'Fandraisana',
    about: 'Momba',
    services: 'Tolotra',
    portfolio: 'Portfolio',
    contact: 'Fifandraisana',
    language: 'Fiteny',
    theme: 'Teny',
    light: 'Mazava',
    dark: 'Maizina',
    system: 'Rafitra',
    welcome: 'Tonga soa',
    login: 'Hiditra',
    register: 'Hisoratra',
    profile: 'Profil',
    logout: 'Hivoaka',
    dashboard: 'Tabilao',
    getStarted: 'Atombohy',
  },
};

const Header = ({ isAuthenticated = false, onLogout, userData = null }) => {
  const navigate = useNavigate();

  const [language, setLanguage] = useState('fr');
  const [darkMode, setDarkMode] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [languageDropdownOpen, setLanguageDropdownOpen] = useState(false);
  const [themeDropdownOpen, setThemeDropdownOpen] = useState(false);
  const [userDropdownOpen, setUserDropdownOpen] = useState(false);

  const userEmail = userData?.email || localStorage.getItem('userEmail') || '';
  const userName = userData?.name || userEmail.split('@')[0] || 'User';

  const navItems = ['home', 'about', 'services', 'portfolio', 'contact'];

  // Initialisation du thème
  useEffect(() => {
    const storedTheme = localStorage.getItem('theme');
    const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

    if (storedTheme === 'dark' || (!storedTheme && systemPrefersDark)) {
      setDarkMode(true);
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, []);

  // Changer thème
  const toggleDarkMode = () => {
    const newDarkMode = !darkMode;
    setDarkMode(newDarkMode);

    if (newDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  };

  const changeLanguage = (lang) => {
    setLanguage(lang);
    setLanguageDropdownOpen(false);
  };

  const changeTheme = (theme) => {
    if (theme === 'system') {
      localStorage.removeItem('theme');
      const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      setDarkMode(systemPrefersDark);
      if (systemPrefersDark) document.documentElement.classList.add('dark');
      else document.documentElement.classList.remove('dark');
    } else {
      const newDarkMode = theme === 'dark';
      setDarkMode(newDarkMode);
      localStorage.setItem('theme', theme);
      if (newDarkMode) document.documentElement.classList.add('dark');
      else document.documentElement.classList.remove('dark');
    }
    setThemeDropdownOpen(false);
  };

  const handleLoginClick = () => {
    navigate('/login');
    setMobileMenuOpen(false);
  };

  const handleRegisterClick = () => {
    navigate('/register');
    setMobileMenuOpen(false);
  };

  const handleLogout = () => {
    if (onLogout) onLogout();
    setMobileMenuOpen(false);
    setUserDropdownOpen(false);
    navigate('/');
  };

  const t = (key) => translations[language][key] || key;

  return (
    <header className="sticky top-0 z-50 w-full border-b border-neutral-200 dark:border-neutral-800 bg-white/80 dark:bg-neutral-950/80 backdrop-blur-md">
      <div className="container mx-auto px-4">
        <div className="flex items-center justify-between h-16">

          {/* LOGO */}
          <Link to="/" className="flex items-center space-x-2">
            <div className="h-10 w-10 rounded-full bg-gradient-to-r from-primary-500 to-secondary-500 flex items-center justify-center">
              <span className="font-bold text-white">L</span>
            </div>
            <span className="text-xl font-bold text-neutral-900 dark:text-white">
              Luxe<span className="text-primary-600 dark:text-primary-400">Design</span>
            </span>
          </Link>

          {/* NAV DESKTOP */}
          <nav className="hidden md:flex items-center space-x-1">
            {navItems.map((item) => (
              <Link
                key={item}
                to={`/${item === 'home' ? '' : item}`}
                className="px-4 py-2 rounded-lg text-neutral-700 dark:text-neutral-300 hover:text-primary-600 dark:hover:text-primary-400"
              >
                {t(item)}
              </Link>
            ))}
          </nav>

          {/* ACTIONS */}
          <div className="flex items-center space-x-2">

            {/* MENU MOBILE */}
            <button
              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
              className="md:hidden p-2"
            >
              {mobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
            </button>

            {/* LANGUE */}
            <div className="relative">
              <button
                onClick={() => {
                  setLanguageDropdownOpen(!languageDropdownOpen);
                  setThemeDropdownOpen(false);
                  setUserDropdownOpen(false);
                }}
                className="flex items-center px-3 py-2 border rounded-lg"
              >
                <Globe size={18} />
                <span>{language.toUpperCase()}</span>
                <ChevronDown size={16} />
              </button>

              {languageDropdownOpen && (
                <div className="absolute right-0 mt-2 w-40 py-2 bg-white dark:bg-neutral-900 border rounded-lg shadow-lg z-50">
                  {['en', 'fr', 'mg'].map((lang) => (
                    <button
                      key={lang}
                      onClick={() => changeLanguage(lang)}
                      className="w-full text-left px-4 py-2 hover:bg-neutral-100 dark:hover:bg-neutral-800"
                    >
                      {lang.toUpperCase()}
                    </button>
                  ))}
                </div>
              )}
            </div>

            {/* THEME */}
            <div className="relative hidden sm:block">
              <button
                onClick={() => {
                  setThemeDropdownOpen(!themeDropdownOpen);
                  setLanguageDropdownOpen(false);
                  setUserDropdownOpen(false);
                }}
                className="flex items-center px-3 py-2 border rounded-lg"
              >
                {darkMode ? <Moon size={18} /> : <Sun size={18} />}
                <ChevronDown size={16} />
              </button>

              {themeDropdownOpen && (
                <div className="absolute right-0 mt-2 w-40 py-2 bg-white dark:bg-neutral-900 border rounded-lg shadow-lg z-50">
                  <button onClick={() => changeTheme('light')} className="w-full text-left px-4 py-2">
                    Clair
                  </button>
                  <button onClick={() => changeTheme('dark')} className="w-full text-left px-4 py-2">
                    Sombre
                  </button>
                  <button onClick={() => changeTheme('system')} className="w-full text-left px-4 py-2">
                    Système
                  </button>
                </div>
              )}
            </div>

            {/* Auth */}
            {isAuthenticated ? (
              <div className="relative">
                <button
                  onClick={() => {
                    setUserDropdownOpen(!userDropdownOpen);
                    setLanguageDropdownOpen(false);
                    setThemeDropdownOpen(false);
                  }}
                  className="flex items-center space-x-2 px-4 py-2 rounded-lg bg-gradient-to-r from-primary-500 to-secondary-500 text-white"
                >
                  <div className="h-6 w-6 rounded-full bg-white/30 flex items-center justify-center">
                    {userName.charAt(0).toUpperCase()}
                  </div>
                  <ChevronDown size={16} />
                </button>

                {userDropdownOpen && (
                  <div className="absolute right-0 mt-2 w-56 py-2 bg-white dark:bg-neutral-900 border rounded-lg shadow-lg z-50">
                    <Link
                      to="/dashboard"
                      className="flex items-center px-4 py-2 hover:bg-neutral-100 dark:hover:bg-neutral-800"
                      onClick={() => setUserDropdownOpen(false)}
                    >
                      <User size={16} />
                      <span>{t('dashboard')}</span>
                    </Link>

                    <button
                      onClick={handleLogout}
                      className="flex w-full text-left items-center px-4 py-2 text-red-600 hover:bg-red-100 dark:hover:bg-red-900/30"
                    >
                      <LogIn size={16} />
                      <span>{t('logout')}</span>
                    </button>
                  </div>
                )}
              </div>
            ) : (
              <div className="hidden md:flex items-center space-x-2">
                <button
                  onClick={handleLoginClick}
                  className="flex items-center px-4 py-2 border rounded-lg"
                >
                  <LogIn size={18} />
                  <span>{t('login')}</span>
                </button>
                <button
                  onClick={handleRegisterClick}
                  className="flex items-center px-4 py-2 rounded-lg bg-gradient-to-r from-primary-500 to-secondary-500 text-white"
                >
                  <UserPlus size={18} />
                  <span>{t('register')}</span>
                </button>
              </div>
            )}
          </div>
        </div>

        {/* MENU MOBILE */}
        {mobileMenuOpen && (
          <div className="md:hidden py-4 space-y-2">
            {navItems.map((item) => (
              <Link
                key={item}
                to={`/${item === 'home' ? '' : item}`}
                onClick={() => setMobileMenuOpen(false)}
                className="block px-4 py-3 rounded-lg hover:bg-neutral-100"
              >
                {t(item)}
              </Link>
            ))}

            {!isAuthenticated ? (
              <>
                <button
                  onClick={handleLoginClick}
                  className="w-full flex items-center justify-center px-4 py-3 border rounded-lg"
                >
                  <LogIn size={20} />
                  <span>{t('login')}</span>
                </button>
                <button
                  onClick={handleRegisterClick}
                  className="w-full flex items-center justify-center px-4 py-3 rounded-lg bg-gradient-to-r from-primary-500 to-secondary-500 text-white"
                >
                  <UserPlus size={20} />
                  <span>{t('register')}</span>
                </button>
              </>
            ) : (
              <>
                <Link
                  to="/dashboard"
                  onClick={() => setMobileMenuOpen(false)}
                  className="flex items-center px-4 py-3 rounded-lg hover:bg-neutral-100"
                >
                  <User size={18} />
                  <span>{t('dashboard')}</span>
                </Link>

                <button
                  onClick={handleLogout}
                  className="w-full flex items-center justify-center px-4 py-3 border rounded-lg text-red-600"
                >
                  <LogIn size={20} />
                  <span>{t('logout')}</span>
                </button>
              </>
            )}
          </div>
        )}
      </div>
    </header>
  );
};

export default Header;
